            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            components.append((color, cells))

    global_freq = Counter(v for row in grid for v in row)
    background = global_freq.most_common(1)[0][0]
    for color, cells in components:
        if len(cells) != 1:
            continue
        y, x = cells[0]

        # If this cell interrupts a filled 2x2 patch, restore that patch color.
        patch_colors = Counter()
        for dy in (-1, 0):
            for dx in (-1, 0):
                positions = ((y + dy, x + dx), (y + dy + 1, x + dx),
                             (y + dy, x + dx + 1), (y + dy + 1, x + dx + 1))
                if all(0 <= yy < h and 0 <= xx < w for yy, xx in positions):
                    vals = [grid[yy][xx] for yy, xx in positions if (yy, xx) != (y, x)]
                    if vals[0] == vals[1] == vals[2]:
                        patch_colors[vals[0]] += 1
        if patch_colors:
            out[y][x] = patch_colors.most_common(1)[0][0]
            continue

        # Otherwise use cardinal neighbors; ties resolve to the global background.
        card = Counter()
        around = Counter()
        for dy in (-1, 0, 1):
            for dx in (-1, 0, 1):
                if dy == dx == 0:
                    continue
                ny, nx = y + dy, x + dx
                if 0 <= ny < h and 0 <= nx < w:
                    around[grid[ny][nx]] += 1
                    if abs(dy) + abs(dx) == 1:
                        card[grid[ny][nx]] += 1
        if not card:
