                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            if len(cells) == 1:
                isolated.append((color, cells[0][0], cells[0][1]))

    global_counts = Counter(v for row in grid for v in row)
    background = global_counts.most_common(1)[0][0]
    for color, y, x in isolated:
        # Local 2x2 consensus: three matching neighbors imply the missing color.
        square = Counter()
        for dy in (-1, 0):
            for dx in (-1, 0):
                coords = ((y+dy, x+dx), (y+dy+1, x+dx),
                          (y+dy, x+dx+1), (y+dy+1, x+dx+1))
                if all(0 <= yy < h and 0 <= xx < w for yy, xx in coords):
                    vals = [grid[yy][xx] for yy, xx in coords if (yy, xx) != (y, x)]
                    if vals[0] == vals[1] == vals[2]:
                        square[vals[0]] += 1
        if square:
            chosen, score = square.most_common(1)[0]
            if score > 1:
                out[y][x] = chosen
                continue

        # A row/column continuation can disambiguate a square-shaped coincidence.
        if x > 0 and x + 1 < w and grid[y][x-1] == grid[y][x+1]:
            out[y][x] = grid[y][x-1]
            continue
        if y > 0 and y + 1 < h and grid[y-1][x] == grid[y+1][x]:
            out[y][x] = grid[y-1][x]
            continue

        # Neighborhood voting; cardinal support dominates diagonal support.
        scores = Counter()
        for dy in (-1, 0, 1):
            for dx in (-1, 0, 1):
                if dy == dx == 0:
                    continue
                ny, nx = y + dy, x + dx
                if 0 <= ny < h and 0 <= nx < w:
                    scores[grid[ny][nx]] += 2 if abs(dy) + abs(dx) == 1 else 1
        scores.pop(color, None)
        if not scores:
            continue
        best = max(scores.values())
        candidates = [v for v, n in scores.items() if n == best]
        # In ambiguous ties, choose the color that continues below, then the
        # global background if present, else the locally most prevalent color.
        below = grid[y+1][x] if y+1 < h else None
        above = grid[y-1][x] if y > 0 else None
        if below in candidates:
            chosen = below
        elif above in candidates:
            chosen = above
        elif background in candidates:
            chosen = background
        else:
            chosen = max(candidates, key=lambda v: (global_counts[v], -v))
        out[y][x] = chosen
